42	import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
43	import ExperiencePanel from "@/components/candidate/ExperiencePanel";
44	import EducationPanel from "@/components/candidate/EducationPanel";
45	import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
46	import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
47	import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
48	import StageTracker from "@/components/candidate/StageTracker";
49	import ScorecardPanel from "@/components/candidate/ScorecardPanel";
50	import ScorecardSummary from "@/components/candidate/ScorecardSummary";
51	import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
52	import CandidateNotesPanel from "@/components/candidate/CandidateNotesPanel";
