64	
65	// ── Local sub-components ────────────────────────────────────────────────────
66	
67	function ScoreRingMini({ score }: { score: number }) {
68	  const size = 56;
69	  const sw = 5;
70	  const r = (size - sw) / 2;
71	  const c = 2 * Math.PI * r;
72	  const v = Math.min(Math.max(score, 0), 100);
73	  const dash = (v / 100) * c;
74	  const color = v >= 70 ? "#22c55e" : v >= 40 ? "#f59e0b" : "#ef4444";
75	  return (
76	    <div
77	      className="relative inline-flex items-center justify-center shrink-0"
78	      style={{ width: size, height: size }}
79	    >
80	      <svg width={size} height={size} className="-rotate-90">
81	        <circle
82	          cx={size / 2}
83	          cy={size / 2}
84	          r={r}
85	          fill="none"
86	          stroke="currentColor"
87	          strokeWidth={sw}
88	          className="text-muted/30"
89	        />
90	        <circle
91	          cx={size / 2}
92	          cy={size / 2}
93	          r={r}
94	          fill="none"
95	          stroke={color}
96	          strokeWidth={sw}
97	          strokeDasharray={`${dash} ${c - dash}`}
98	          strokeLinecap="round"
99	        />
100	      </svg>
101	      <span
102	        className="absolute text-sm font-bold tabular-nums"
103	        style={{ color }}
104	      >
105	        {Math.round(v)}
106	      </span>
107	    </div>
108	  );
109	}
110	
111	function MustHaveSkillsGrid({
112	  matched = [],
113	  missing = [],
114	}: {
115	  matched?: string[];
116	  missing?: string[];
117	}) {
118	  if (!matched.length && !missing.length) return null;
119	  return (
120	    <div>
121	      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
122	        Must-Have Skills
123	      </p>
124	      <div className="flex flex-wrap gap-2">
125	        {matched.map((s) => (
126	          <span
127	            key={s}
128	            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800"
129	          >
130	            <CheckCircle2 className="h-3 w-3" />
131	            {s}
132	          </span>
133	        ))}
134	        {missing.map((s) => (
135	          <span
136	            key={s}
137	            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-200 dark:bg-red-950/40 dark:text-red-400 dark:border-red-800"
138	          >
139	            <XCircle className="h-3 w-3" />
140	            {s}
141	          </span>
142	        ))}
143	      </div>
144	    </div>
145	  );
146	}
147	
148	// ── Props & helpers ──────────────────────────────────────────────────────────
149	
150	interface CandidateDetailSheetProps {
151	  result: Result | null;
152	  isOpen: boolean;
153	  onClose: () => void;
154	  jobId?: string | null;
155	  jobTitle?: string | null;
156	  teamId?: string | null;
157	  formatCandidateName: (filename: string) => string;
158	  onDownload: (filePath: string, filename: string) => void;
159	  onDismiss: (resumeId: string) => void;
160	  currentStage?: HiringStage | null;
161	  stageUpdatedAt?: string | null;
162	  onStageChange?: (resumeId: string, stage: HiringStage) => void;
163	  tags?: CandidateTag[];
164	  teamMembers?: TeamMember[];
165	  onAddTag?: (params: { resumeId: string; tag: string; color?: string }) => void;
166	  onRemoveTag?: (tagId: string) => void;
167	  onAssigned?: (resumeId: string, userId: string | null) => void;
168	  blindMode?: boolean;
169	}
170	
171	const getStrengthLabel = (
172	  score: number
173	): { label: string; variant: "success" | "warning" | "destructive" } => {
174	  if (score >= 70) return { label: "Strong", variant: "success" };
175	  if (score >= 40) return { label: "Good", variant: "warning" };
176	  return { label: "Weak", variant: "destructive" };
177	};
178	
179	// ── Main component ───────────────────────────────────────────────────────────
180	
181	const CandidateDetailSheet = ({
182	  result: r,
183	  isOpen,
184	  onClose,
185	  jobId,
186	  jobTitle,
187	  teamId,
188	  formatCandidateName,
189	  onDownload,
190	  onDismiss,
191	  currentStage,
192	  stageUpdatedAt,
193	  onStageChange,
194	  tags = [],
195	  teamMembers = [],
196	  onAddTag,
197	  onRemoveTag,
198	  onAssigned,
199	  blindMode = false,
200	}: CandidateDetailSheetProps) => {
201	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
202	  const [scheduleOpen, setScheduleOpen] = useState(false);
203	  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
204	  const [whatsappOpen, setWhatsappOpen] = useState(false);
205	  const [activeTab, setActiveTab] = useState("overview");
206	
207	  // Reset tab to overview each time the sheet opens
208	  useEffect(() => {
209	    if (isOpen) setActiveTab("overview");
210	  }, [isOpen]);
211	
212	  if (!r) return null;
213	
214	  const strength = getStrengthLabel(r.overall_score);
215	  const linkedinUrl = extractLinkedInUrl(r);
216	  const candidateName = r.candidate_name || formatCandidateName(r.filename);
217	  const initials = candidateName
218	    .split(" ")
219	    .slice(0, 2)
220	    .map((n: string) => n[0])
221	    .join("")
222	    .toUpperCase();
223	
224	  return (
225	    <>
226	      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
227	        <SheetContent
228	          side="right"
229	          className="sm:max-w-[780px] w-full p-0 flex flex-col gap-0 [&>button]:hidden"
230	        >
231	          {/* ── Header ──────────────────────────────────────────────────── */}
232	          <div className="bg-gradient-to-b from-muted/40 to-card px-6 pt-5 pb-4 shrink-0 border-b border-border relative min-h-[140px]">
233	            {/* Close button */}
234	            <button
235	              onClick={onClose}
236	              className="absolute top-4 right-4 rounded-md p-1 opacity-60 hover:opacity-100 hover:bg-muted/60 transition-all"
237	            >
238	              <X className="h-4 w-4" />
239	            </button>
240	
241	            {/* Identity row */}
242	            <div className="flex items-start gap-4 pr-8">
243	              {/* Avatar with score-colored ring */}
244	              <div
245	                className="h-14 w-14 rounded-full flex items-center justify-center shrink-0 ring-2 ring-offset-2 ring-offset-card"
246	                style={{
247	                  backgroundColor: `${r.overall_score >= 70 ? "#22c55e" : r.overall_score >= 40 ? "#f59e0b" : "#ef4444"}10`,
248	                  // @ts-ignore -- ring color
249	                  "--tw-ring-color": r.overall_score >= 70 ? "#22c55e" : r.overall_score >= 40 ? "#f59e0b" : "#ef4444",
250	                } as React.CSSProperties}
251	              >
252	                <span className="text-sm font-bold text-foreground">{initials}</span>
253	              </div>
254	
255	              {/* Name + role + meta */}
256	              <div className="flex-1 min-w-0">
257	                <h2 className="text-lg font-semibold text-foreground truncate leading-tight">
258	                  {blindMode ? "Candidate" : candidateName}
259	                </h2>
260	                {/* Role from parsed resume */}
261	                {r.parsed_json?.job_title && (
262	                  <p className="text-sm text-muted-foreground truncate mt-0.5">
263	                    {r.parsed_json.job_title}
264	                    {r.parsed_json?.company ? ` at ${r.parsed_json.company}` : ""}
265	                  </p>
266	                )}
267	                <div className="flex items-center gap-3 mt-1 flex-wrap">
268	                  {r.candidate_location && (
269	                    <span className="flex items-center gap-1 text-xs text-muted-foreground">
270	                      <MapPin className="h-3 w-3 shrink-0" />
271	                      {r.candidate_location}
272	                    </span>
273	                  )}
274	                  {r.candidate_email && (
275	                    <span className="text-xs text-muted-foreground truncate max-w-[200px]">
276	                      {r.candidate_email}
277	                    </span>
278	                  )}
279	                </div>
280	              </div>
281	
282	              {/* Score ring */}
283	              <ScoreRingMini score={r.overall_score ?? 0} />
284	            </div>
285	
286	            {/* Badge + confidence row */}
287	            <div className="flex items-center gap-2 mt-3 flex-wrap">
288	              <Badge variant={strength.variant}>{strength.label}</Badge>
289	              {r.scoring_version === "heuristic" && (
290	                <Badge variant="secondary">Quick</Badge>
291	              )}
292	              {r.confidence != null && (
293	                <Badge variant="outline" className="text-muted-foreground">
294	                  {r.confidence}% confidence
295	                </Badge>
296	              )}
297	              {stageUpdatedAt && (
298	                <span className="text-[11px] text-muted-foreground/60 ml-auto">
299	                  Updated {new Date(stageUpdatedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
300	                </span>
301	              )}
302	            </div>
303	
304	            {/* Action row */}
305	            <div className="flex items-center gap-1 mt-3 flex-wrap">
306	              <TooltipProvider>
307	                {r.candidate_phone && (
308	                  <>
309	                    <Tooltip>
310	                      <TooltipTrigger asChild>
311	                        <Button
312	                          variant="outline"
313	                          size="icon"
314	                          className="h-8 w-8"
315	                          onClick={() => {
316	                            navigator.clipboard.writeText(r.candidate_phone!);
317	                            toast.success("Phone copied!");
318	                          }}
319	                        >
320	                          <Phone className="h-4 w-4" />
321	                        </Button>
322	                      </TooltipTrigger>
323	                      <TooltipContent>Copy phone</TooltipContent>
324	                    </Tooltip>
325	
326	                    <Tooltip>
327	                      <TooltipTrigger asChild>
328	                        <Button
329	                          variant="outline"
330	                          size="icon"
331	                          className="h-8 w-8 border-[#25D366]/30 text-[#25D366] hover:bg-[#25D366]/10"
332	                          onClick={() => setWhatsappOpen(true)}
333	                        >
334	                          <MessageCircle className="h-4 w-4" />
335	                        </Button>
336	                      </TooltipTrigger>
337	                      <TooltipContent>WhatsApp</TooltipContent>
338	                    </Tooltip>
339	                  </>
340	                )}
341	
342	                {r.candidate_email && (
343	                  <Tooltip>
344	                    <TooltipTrigger asChild>
345	                      <Button
346	                        variant="outline"
347	                        size="icon"
348	                        className="h-8 w-8"
349	                        onClick={() => setEmailDialogOpen(true)}
350	                      >
351	                        <Mail className="h-4 w-4" />
352	                      </Button>
353	                    </TooltipTrigger>
354	                    <TooltipContent>Send email</TooltipContent>
355	                  </Tooltip>
356	                )}
357	
358	                {jobId && (
359	                  <Tooltip>
360	                    <TooltipTrigger asChild>
361	                      <Button
362	                        variant="outline"
363	                        size="icon"
364	                        className="h-8 w-8"
365	                        onClick={() => setScheduleOpen(true)}
366	                      >
367	                        <Calendar className="h-4 w-4" />
368	                      </Button>
369	                    </TooltipTrigger>
370	                    <TooltipContent>Schedule interview</TooltipContent>
371	                  </Tooltip>
372	                )}
373	              </TooltipProvider>
374	
375	              {/* Stage tracker — right-aligned */}
376	              {onStageChange && (
377	                <div className="ml-auto">
378	                  <StageTracker
379	                    currentStage={currentStage || "applied"}
380	                    updatedAt={stageUpdatedAt}
381	                    onStageChange={(stage) => onStageChange(r.resume_id, stage)}
382	                  />
383	                </div>
384	              )}
385	
386	              {/* Overflow dropdown */}
387	              <DropdownMenu>
388	                <DropdownMenuTrigger asChild>
389	                  <Button variant="outline" size="icon" className="h-8 w-8 shrink-0">
390	                    <MoreHorizontal className="h-4 w-4" />
391	                  </Button>
392	                </DropdownMenuTrigger>
393	                <DropdownMenuContent align="end" className="w-44">
394	                  {r.file_path && (
395	                    <DropdownMenuItem
396	                      onClick={() => onDownload(r.file_path!, r.filename)}
397	                    >
398	                      <Download className="h-3.5 w-3.5 mr-2" />
399	                      Download resume
400	                    </DropdownMenuItem>
401	                  )}
402	                  {linkedinUrl && (
403	                    <DropdownMenuItem
404	                      onClick={() =>
405	                        window.open(linkedinUrl, "_blank", "noopener,noreferrer")
406	                      }
407	                    >
408	                      <Linkedin className="h-3.5 w-3.5 mr-2" />
409	                      LinkedIn profile
410	                    </DropdownMenuItem>
411	                  )}
412	                  {jobId && teamId && (
413	                    <DropdownMenuItem asChild>
414	                      <div className="flex items-center">
415	                        <Bookmark className="h-3.5 w-3.5 mr-2" />
416	                        <AddToPoolButton
417	                          resumeId={r.resume_id}
418	                          jobId={jobId}
419	                          teamId={teamId}
420	                          isInPool={(r as any).in_talent_pool ?? false}
421	                          variant="ghost"
422	                        />
423	                      </div>
424	                    </DropdownMenuItem>
425	                  )}
426	                  <DropdownMenuSeparator />
427	                  {onStageChange && (
428	                    <DropdownMenuItem
429	                      className="text-destructive focus:text-destructive"
430	                      onClick={() => setRejectDialogOpen(true)}
431	                    >
432	                      <UserX className="h-3.5 w-3.5 mr-2" />
433	                      Reject
434	                    </DropdownMenuItem>
435	                  )}
436	                  <DropdownMenuItem
437	                    className="text-destructive focus:text-destructive"
438	                    onClick={() => { onDismiss(r.resume_id); onClose(); }}
439	                  >
440	                    <Archive className="h-3.5 w-3.5 mr-2" />
441	                    Archive
442	                  </DropdownMenuItem>
443	                </DropdownMenuContent>
444	              </DropdownMenu>
445	            </div>
446	          </div>
447	
448	          {/* ── Tabs ────────────────────────────────────────────────────── */}
449	          <Tabs
450	            value={activeTab}
451	            onValueChange={setActiveTab}
452	            className="flex flex-col flex-1 min-h-0"
453	          >
454	            <TabsList className="px-6 h-10 border-b border-border bg-transparent rounded-none justify-start gap-0 shrink-0">
455	              {([
456	                { value: "overview", label: "Overview", icon: Eye },
457	                { value: "analysis", label: "Analysis", icon: BarChart3 },
458	                { value: "team", label: "Team", icon: Users },
459	                { value: "history", label: "History", icon: Clock },
460	              ] as const).map(({ value, label, icon: Icon }) => (
461	                <TabsTrigger
462	                  key={value}
463	                  value={value}
464	                  className="text-sm rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:text-foreground data-[state=active]:shadow-none text-muted-foreground px-3 h-10 gap-1.5"
465	                >
466	                  <Icon className="h-3.5 w-3.5" />
467	                  {label}
468	                </TabsTrigger>
469	              ))}
470	            </TabsList>
471	
472	            {/* ── Overview tab ──────────────────────────────────────────── */}
473	            <TabsContent value="overview" className="flex-1 min-h-0 mt-0">
474	              <ScrollArea className="h-full">
475	                <div className="px-6 py-6 space-y-5">
476	                  {/* Quick AI summary */}
477	                  {(r.explanation_json?.summary || r.summary) && (
478	                    <div className="rounded-xl border border-primary/15 bg-primary/[0.03] p-4">
479	                      <div className="flex items-start gap-2.5">
480	                        <Sparkles className="h-4 w-4 text-primary shrink-0 mt-0.5" />
481	                        <p className="text-sm leading-relaxed text-foreground">
482	                          {r.explanation_json?.summary || r.summary}
483	                        </p>
484	                      </div>
485	                    </div>
486	                  )}
487	
488	                  {/* Score breakdown mini bars */}
489	                  {(() => {
490	                    const cat = r.category_scores_json ?? {};
491	                    const sk = cat["Skills"]?.score ?? cat["Technical Skills"]?.score ?? cat["skills"]?.score ?? 0;
492	                    const ex = cat["Experience"]?.score ?? cat["experience"]?.score ?? 0;
493	                    const ed = cat["Education"]?.score ?? cat["education"]?.score ?? 0;
494	                    if (!sk && !ex && !ed) return null;
495	                    return (
496	                      <div className="grid grid-cols-3 gap-3">
497	                        {[
498	                          { label: "Skills", value: sk },
499	                          { label: "Experience", value: ex },
500	                          { label: "Education", value: ed },
501	                        ].filter((b) => b.value > 0).map((b) => (
502	                          <div key={b.label} className="rounded-lg border border-border p-3 text-center">
503	                            <p className="text-lg font-bold tabular-nums" style={{ color: b.value >= 70 ? "#22c55e" : b.value >= 40 ? "#f59e0b" : "#ef4444" }}>{Math.round(b.value)}</p>
504	                            <p className="text-[11px] text-muted-foreground font-medium mt-0.5">{b.label}</p>
505	                          </div>
506	                        ))}
507	                      </div>
508	                    );
509	                  })()}
510	
511	                  {/* Must-have skills with progress */}
512	                  {(() => {
513	                    const matched = (r.matched_must_haves as string[] | undefined) ?? [];
514	                    const missing = (r.missing_must_haves as string[] | undefined) ?? [];
515	                    const total = matched.length + missing.length;
516	                    if (!total) return null;
517	                    return (
518	                      <div>
519	                        <div className="flex items-center justify-between mb-2">
520	                          <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider">
521	                            Must-Have Skills
522	                          </p>
523	                          <span className="text-xs font-medium tabular-nums text-muted-foreground">
524	                            {matched.length}/{total} matched
525	                          </span>
526	                        </div>
527	                        {/* Progress bar */}
528	                        <div className="h-1.5 rounded-full bg-muted overflow-hidden mb-3">
529	                          <div
530	                            className="h-full rounded-full bg-emerald-500 transition-all duration-500"
531	                            style={{ width: `${(matched.length / total) * 100}%` }}
532	                          />
533	                        </div>
534	                        <div className="flex flex-wrap gap-2">
535	                          {matched.map((s) => (
536	                            <span
537	                              key={s}
538	                              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800"
539	                            >
540	                              <CheckCircle2 className="h-3 w-3" />
541	                              {s}
542	                            </span>
543	                          ))}
544	                          {missing.map((s) => (
545	                            <span
546	                              key={s}
547	                              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-200 dark:bg-red-950/40 dark:text-red-400 dark:border-red-800"
548	                            >
549	                              <XCircle className="h-3 w-3" />
550	                              {s}
551	                            </span>
552	                          ))}
553	                        </div>
554	                      </div>
555	                    );
556	                  })()}
557	
558	                  <StrengthsGapsPanel result={r} />
559	                  <InterviewQuestionsPanel result={r} />
560	                  {(onAddTag || onRemoveTag) && (
561	                    <CandidateTagInput
562	                      resumeId={r.resume_id}
563	                      tags={tags}
564	                      onAdd={onAddTag ?? (() => {})}
565	                      onRemove={onRemoveTag ?? (() => {})}
566	                    />
567	                  )}
568	                </div>
569	              </ScrollArea>
570	            </TabsContent>
571	
572	            {/* ── Analysis tab ──────────────────────────────────────────── */}
573	            <TabsContent value="analysis" className="flex-1 min-h-0 mt-0">
574	              <ScrollArea className="h-full">
575	                <div className="px-6 py-6 space-y-6">
576	                  {/* Section: AI Summary */}
577	                  <div>
578	                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-3">AI Summary</p>
579	                    <CandidateSummaryCard
580	                      result={r}
581	                      candidateName={candidateName}
582	                      compact={false}
583	                    />
584	                  </div>
585	
