4	import type { Result } from "@/pages/Index";
5	
6	interface JDAlignedPanelProps {
7	  result: Result;
8	}
9	
10	type RecLevel = "success" | "secondary" | "warning" | "destructive";
11	
12	const getRecommendation = (score: number, hardFit: boolean | undefined, isHeuristic: boolean): { text: string; label: string; variant: RecLevel } => {
13	  if (isHeuristic) return { text: "Needs full AI scoring for reliable recommendation", label: "Pending", variant: "warning" };
14	  if (score >= 70 && hardFit !== false) return { text: "Strong core fit, gaps are learnable", label: "Shortlist", variant: "success" };
15	  if (score >= 50 && hardFit !== false) return { text: "Decent match, review before interview", label: "Consider", variant: "secondary" };
16	  if (score >= 40) return { text: "Has strengths but missing critical items", label: "Review", variant: "warning" };
17	  return { text: "Significant gaps for this role", label: "Pass", variant: "destructive" };
18	};
19	
20	const JDAlignedPanel = ({ result: r }: JDAlignedPanelProps) => {
21	  const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.map(String) : [];
22	  const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.map(String) : [];
23	  const strengths = Array.isArray(r.strengths_json) ? r.strengths_json.map(String) : [];
24	  const gaps = Array.isArray(r.gaps_json) ? r.gaps_json.map(String) : [];
25	  const confidence = r.confidence ?? 0;
26	  const interviewQs = Array.isArray(r.interview_questions) ? r.interview_questions.map(String) : [];
27	  const isHeuristic = r.scoring_version === "heuristic";
28	  const isInsufficient = r.scoring_version === "insufficient";
29	
30	  if (isInsufficient) return null;
31	
32	  const totalMustHave = matched.length + missing.length;
33	  const mustHavePercent = totalMustHave > 0 ? Math.round((matched.length / totalMustHave) * 100) : 0;
34	
35	  const rawMatchedPref = r.explanation_json?.matched_preferred;
36	  const matchedPreferred: string[] = Array.isArray(rawMatchedPref) ? rawMatchedPref.map(String)
37	    : (isHeuristic ? [] : strengths.filter((s) => !matched.some((m) => s.toLowerCase().includes(m.toLowerCase()))));
38	  const rawMissingPref = r.explanation_json?.missing_preferred;
39	  const missingPreferred: string[] = Array.isArray(rawMissingPref) ? rawMissingPref.map(String)
40	    : (isHeuristic ? [] : gaps.filter((g) => !missing.some((m) => g.toLowerCase().includes(m.toLowerCase()))));
41	  const totalPreferred = matchedPreferred.length + missingPreferred.length;
42	
43	  const rec = getRecommendation(r.overall_score, r.hard_fit, isHeuristic);
44	
45	  if (totalMustHave === 0 && totalPreferred === 0 && !r.explanation_json?.why_ranked_here) return null;
46	
47	  return (
48	    <div className="rounded-xl border border-border overflow-hidden">
49	      {/* Recommendation hero */}
50	      <div className="bg-foreground/[0.03] px-5 py-4 space-y-3">
51	        <div className="flex items-center justify-between flex-wrap gap-2">
52	          <div className="flex items-center gap-3">
53	            <h4 className="text-sm font-semibold text-foreground">JD Alignment</h4>
54	            {totalMustHave > 0 && (
55	              <span className="text-sm font-semibold tabular-nums text-primary">{mustHavePercent}%</span>
56	            )}
57	          </div>
58	          <div className="flex items-center gap-2">
59	            <Badge variant={rec.variant} className="text-sm px-3 py-1">{rec.label}</Badge>
60	            {confidence > 0 && <Badge variant="outline">{confidence}% confidence</Badge>}
61	          </div>
62	        </div>
63	        <p className="text-sm text-muted-foreground">{rec.text}</p>
64	
65	        {/* Quick stats */}
66	        {totalMustHave > 0 && (
67	          <div className="flex items-center gap-4 text-xs">
68	            <span className="text-emerald-600 dark:text-emerald-400 font-medium">{matched.length} matched</span>
69	            {missing.length > 0 && <span className="text-red-500 font-medium">{missing.length} missing</span>}
70	            {totalPreferred > 0 && <span className="text-muted-foreground">{matchedPreferred.length}/{totalPreferred} preferred</span>}
71	          </div>
72	        )}
73	      </div>
74	
75	      <Separator />
76	
77	      {/* Requirements grid */}
78	      <div className="p-5">
79	        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
80	          {/* Must Have */}
81	          {totalMustHave > 0 && (
82	            <div className="space-y-3">
83	              <h5 className="text-xs font-semibold text-foreground uppercase tracking-wider">Must Have</h5>
84	              <div className="space-y-2">
85	                {matched.map((item, i) => (
86	                  <div key={`m-${i}`} className="flex items-start gap-2 text-sm leading-snug">
87	                    <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0 mt-0.5" />
88	                    <span className="text-foreground">{item}</span>
89	                  </div>
90	                ))}
91	                {missing.map((item, i) => (
92	                  <div key={`x-${i}`} className="flex items-start gap-2 text-sm leading-snug">
93	                    <XCircle className="h-4 w-4 text-red-400 shrink-0 mt-0.5" />
94	                    <span className="text-muted-foreground">{item}</span>
95	                  </div>
96	                ))}
97	              </div>
98	            </div>
99	          )}
100	
101	          {/* Preferred */}
102	          {totalPreferred > 0 && (
103	            <div className="space-y-3">
104	              <h5 className="text-xs font-semibold text-foreground uppercase tracking-wider">Preferred</h5>
105	              <div className="space-y-2">
106	                {matchedPreferred.map((item, i) => (
107	                  <div key={`pm-${i}`} className="flex items-start gap-2 text-sm leading-snug">
108	                    <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0 mt-0.5" />
109	                    <span className="text-foreground">{item}</span>
110	                  </div>
111	                ))}
112	                {missingPreferred.map((item, i) => (
113	                  <div key={`px-${i}`} className="flex items-start gap-2 text-sm leading-snug">
114	                    <XCircle className="h-4 w-4 text-red-400 shrink-0 mt-0.5" />
115	                    <span className="text-muted-foreground">{item}</span>
116	                  </div>
117	                ))}
118	              </div>
119	            </div>
120	          )}
121	
122	          {/* AI Insight */}
123	          <div className="space-y-3">
124	            <h5 className="text-xs font-semibold text-foreground uppercase tracking-wider flex items-center gap-1.5">
125	              <Eye className="h-3.5 w-3.5 text-primary" /> AI Insight
126	            </h5>
127	
128	            {r.explanation_json?.why_ranked_here && (
129	              <p className="text-sm text-foreground/80 leading-relaxed">{r.explanation_json.why_ranked_here}</p>
130	            )}
131	
132	            {interviewQs.length > 0 && (
133	              <div className="rounded-lg bg-primary/5 border border-primary/10 p-3 space-y-1">
134	                <h6 className="text-xs text-primary font-semibold">Interview focus</h6>
135	                <p className="text-sm text-foreground/80 leading-relaxed">{interviewQs[0]}</p>
136	              </div>
137	            )}
138	
139	            {r.explanation_json?.key_tradeoffs && (
140	              <p className="text-xs text-muted-foreground leading-relaxed">{r.explanation_json.key_tradeoffs}</p>
141	            )}
142	          </div>
143	        </div>
144	      </div>
145	    </div>
146	  );
147	};
